import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
const types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.wasm':'application/wasm','.png':'image/png','.webp':'image/webp','.svg':'image/svg+xml','.glb':'model/gltf-binary','.webm':'audio/webm','.m4a':'audio/mp4','.ktx2':'image/ktx2'};
for(const [side,port] of [['baseline',4973],['candidate',4974]]) {
 const root=path.resolve('test-results/r2-l10perf/'+(side==='candidate'?'candidate-final-dist':side+'-dist')),publicRoot=path.resolve('public');
 http.createServer((req,res)=>{
  const name=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname),p=name==='/'?'/index.html':name;
  if(p==='/__perf6__/api.js'){res.setHeader('Content-Type','text/javascript');res.end(fs.readFileSync('test-results/r2-l10perf/public-adapter.js'));return;}
  if(p.includes('..')){res.writeHead(400).end();return;}
  const file=[root,publicRoot].map(r=>path.join(r,p)).find(f=>fs.existsSync(f)&&fs.statSync(f).isFile());
  if(!file){console.error(side,'404',p);res.writeHead(404).end(p);return;}
  res.setHeader('Content-Type',types[path.extname(file)]??'application/octet-stream');res.setHeader('Cache-Control','no-cache');if(p.startsWith('/build/index-')&&p.endsWith('.js')&&req.headers.referer?.includes('testApi=1')) {const original=fs.readFileSync(file,'utf8');const re=/const (\w+)=new (\w+)\((\w+)\),(\w+)=\(async\(\)=>\{await \1\.init\(\)\}\)\(\);try\{/;if(!re.test(original))throw Error('Missing bootstrap '+side);res.end(original.replace(re,(match,g,cls,params,ready)=>match.replace('try{',`if(new URLSearchParams(location.search).get("testApi")==="1")await import("/__perf6__/api.js").then(m=>m.install(${g},${ready}));try{`)));return;}
  res.setHeader('Content-Length',fs.statSync(file).size);fs.createReadStream(file).pipe(res);
 }).listen(port,'127.0.0.1',()=>console.log(side,port));
}

