root=pathlib.Path.cwd(); out=root/'test-results/r2-l10perf'; files=['src/render/CrowdView.ts','src/render/characters/StaticCorpses.ts']; saved={f:(root/f).read_bytes() for f in files}
(out/'vite.config.ts').write_text("import config from '../../vite.config';\nexport default {...config,build:{...config.build,copyPublicDir:false,outDir:process.env.L10_BUILD_OUT}};\n")
records=[]
try:
 for side in ['baseline','candidate']:
  for f in files:
   data=subprocess.check_output(['git','show','daada5d:'+f]) if side=='baseline' else saved[f]
   (root/f).write_bytes(data)
  start=time.time(); env={**os.environ,'NODE_ENV':'production','VITE_QA_HOOKS':'0','L10_BUILD_OUT':str(out/('candidate-final-dist' if side=='candidate' else side+'-dist'))}
  with (out/(side+'-build.log')).open('w') as log:
